files.content:
.root {
  --vt-surface: #ffffff;
  --vt-surface-2: #fffafa;
  --vt-surface-deep: #2a2a2a;
  --vt-ink: #2a2a2a;
  --vt-ink-soft: #5c5c5c;
  --vt-on-deep: #ffffff;
  --vt-accent: #fb5849;
  --vt-on-accent: #ffffff;
  --vt-accent-ink: #fb5849;
  --vt-accent-on-deep: #fb5849;
  --vt-line: #ececec;

  font-family: 'Manrope', sans-serif;
  color: var(--vt-ink);
  background: var(--vt-surface);
  line-height: 1.6;
  scroll-behavior: smooth;
}

.root * {
  box-sizing: border-box;
}

.root :where(a) {
  color: inherit;
  text-decoration: none;
}

.root :where(h1, h2, h3, h4, h5, h6) {
  margin: 0;
  font-weight: 700;
  line-height: 1.2;
}

.root :where(p) {
  margin: 0;
}

.root :where(ul) {
  margin: 0;
  padding: 0;
  list-style: none;
}

.root :where(img) {
  display: block;
  max-width: 100%;
}

.root :where(button) {
  font: inherit;
}

.root a:focus-visible,
.root button:focus-visible {
  outline: 2px solid var(--vt-accent);
  outline-offset: 2px;
}

.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--vt-surface);
  border-bottom: 1px solid var(--vt-line);
}

.navIn {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0.9rem 2rem;
  gap: 1rem;
}

.logo {
  display: flex;
  align-items: center;
  font-weight: 800;
  font-size: 1.35rem;
  letter-spacing: 0.02em;
}

.brand {
  display: inline-flex;
}

.navLinks {
  display: flex;
  gap: 2rem;
  align-items: center;
}

.navLinks a {
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: 0.04em;
  transition: color 0.2s ease;
}

.root .navLinks a:hover,
.root .navLinks a:focus-visible {
  color: var(--vt-accent);
}

.hero {
  display: grid;
  grid-template-columns: minmax(300px, 0.9fr) 1.4fr;
  background: var(--vt-surface-deep);
}

.heroNoMedia {
  grid-template-columns: 1fr;
}

.heroLeft {
  background: var(--vt-surface-deep);
  color: var(--vt-on-deep);
  padding: 4rem clamp(1.5rem, 4vw, 4rem);
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 1.25rem;
}

.heroKicker {
  text-transform: uppercase;
  letter-spacing: 0.28em;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--vt-accent-on-deep);
}

.heroTitle {
  font-family: 'Fraunces', serif;
  font-size: clamp(2.4rem, 5vw, 4.2rem);
  color: var(--vt-on-deep);
}

.heroTag {
  color: rgba(255, 255, 255, 0.78);
  max-width: 30rem;
  font-size: 1.05rem;
}

.heroButton {
  align-self: flex-start;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  padding: 0.85rem 2rem;
  border-radius: 2rem;
  font-weight: 700;
  transition: opacity 0.2s ease, transform 0.2s ease;
}

.root .heroButton:hover,
.root .heroButton:focus-visible {
  opacity: 0.9;
  transform: translateY(-2px);
}

.heroSlider {
  display: flex;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  background: var(--vt-surface-deep);
  scrollbar-width: none;
}

.heroSlider::-webkit-scrollbar {
  display: none;
}

.heroSlide {
  flex: 0 0 100%;
  scroll-snap-align: start;
  min-height: 620px;
  max-height: 700px;
}

.heroSlide img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.about {
  max-width: 1200px;
  margin: 0 auto;
  padding: 5rem 2rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.kicker {
  display: block;
  text-transform: uppercase;
  letter-spacing: 0.24em;
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--vt-accent-ink);
  margin-bottom: 1rem;
}

.aboutText h2 {
  font-family: 'Fraunces', serif;
  font-size: clamp(2rem, 4vw, 3rem);
  margin-bottom: 1.5rem;
}

.aboutText p {
  color: var(--vt-ink-soft);
  margin-bottom: 1rem;
}

.aboutMedia {
  position: relative;
  padding: 0 0 2rem 2rem;
}

.aboutMain img {
  width: 100%;
  border-radius: 1rem;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  box-shadow: 0 2rem 4rem rgba(0, 0, 0, 0.14);
}

.aboutThumbs {
  display: flex;
  gap: 1rem;
  margin-top: -2.5rem;
  padding-left: 2rem;
  position: relative;
  z-index: 2;
}

.aboutThumbs img {
  width: calc((100% - 2rem) / 3);
  height: 5.5rem;
  object-fit: cover;
  border-radius: 0.75rem;
  border: 4px solid var(--vt-surface);
  box-shadow: 0 0.5rem 1.5rem rgba(0, 0, 0, 0.1);
}

.services {
  background: var(--vt-surface-2);
  padding: 5rem 2rem;
}

.sectionHead {
  max-width: 800px;
  margin: 0 auto 3rem;
  text-align: center;
}

.sectionHead h2 {
  font-family: 'Fraunces', serif;
  font-size: clamp(2rem, 4vw, 3rem);
}

.menuTrack {
  display: flex;
  gap: 1.5rem;
  overflow-x: auto;
  scroll-snap-type: x mandatory;
  padding: 0.5rem 0.25rem 1.5rem;
  max-width: 1200px;
  margin: 0 auto;
  scrollbar-width: thin;
  scrollbar-color: var(--vt-accent) transparent;
}

.menuCard {
  position: relative;
  flex: 0 0 320px;
  scroll-snap-align: start;
  background: var(--vt-surface);
  border: 1px solid var(--vt-line);
  border-radius: 1rem;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 1rem 2rem rgba(0, 0, 0, 0.06);
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}

.menuCard:hover {
  transform: translateY(-4px);
  box-shadow: 0 1.5rem 2.5rem rgba(0, 0, 0, 0.1);
}

.menuImg {
  width: 100%;
  height: 220px;
  object-fit: cover;
}

.menuBody {
  padding: 1.75rem 1.5rem 1.5rem;
}

.menuNum {
  position: absolute;
  top: 1rem;
  right: 1rem;
  width: 3rem;
  height: 3rem;
  background: var(--vt-accent);
  color: var(--vt-on-accent);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 0.9rem;
  box-shadow: 0 0.5rem 1rem rgba(0, 0, 0, 0.15);
}

.menuBody h3 {
  font-size: 1.3rem;
  margin-bottom: 0.5rem;
}

.menuBody p {
  color: var(--vt-ink-soft);
  font-size: 0.95rem;
}

.gallery {
  max-width: 1200px;
  margin: 0 auto;
  padding: 5rem 2rem;
}

.galleryGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.galleryItem {
  position: relative;
  margin: 0;
  border-radius: 1rem;
  overflow: hidden;
  aspect-ratio: 4 / 3;
  background: var(--vt-surface-2);
}

.galleryItem img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s ease;
}

.galleryItem:hover img {
  transform: scale(1.05);
}

.galleryItem figcaption {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 1.5rem 1.25rem 1rem;
  background: linear-gradient(180deg, transparent, rgba(42, 42, 42, 0.8));
  color: var(--vt-on-deep);
}

.galleryItem h3 {
  font-size: 1.1rem;
  margin-bottom: 0.15rem;
}

.galleryItem p {
  font-size: 0.85rem;
  opacity: 0.9;
}

.contact {
  background: var(--vt-surface-deep);
  padding: 5rem 2rem;
  color: var(--vt-on-deep);
}

.contactInner {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
}

.contactInfo .kicker {
  color: var(--vt-accent-on-deep);
}

.contactInfo h2 {
  font-family: 'Fraunces', serif;
  font-size: clamp(2rem, 4vw, 3rem);
  color: var(--vt-on-deep);
  margin-bottom: 1rem;
}

.contactInfo > p {
  color: rgba(255, 255, 255, 0.75);
  margin-bottom: 1.5rem;
  max-width: 32rem;
}

.contactList {
  display: grid;
  gap: 0.65rem;
  margin: 0 0 1.5rem;
}

.contactList div {
  display: flex;
  gap: 0.75rem;
}

.contactList dt {
  min-width: 7rem;
  font-weight: 700;
  color: var(--vt-on-deep);
}

.contactList dd {
  margin: 0;
  color: rgba(255, 255, 255, 0.8);
}

.contactCard {
  background: var(--vt-surface);
  color: var(--vt-ink);
  border-radius: 1rem;
  padding: 2rem;
  box-shadow: 0 2rem 4rem rgba(0, 0, 0, 0.35);
  min-height: 320px;
}

.root .contactCard a {
  color: var(--vt-accent-ink);
}

.footer {
  background: var(--vt-surface-deep);
  border-top: 1px solid rgba(255, 255, 255, 0.12);
  padding: 2rem;
}

.footerInner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1rem;
  text-align: center;
  color: var(--vt-on-deep);
}

.footer p {
  color: rgba(255, 255, 255, 0.6);
  font-size: 0.9rem;
}

@media (max-width: 900px) {
  .navIn {
    padding: 0.9rem 1rem;
  }

  .navLinks {
    gap: 1rem;
  }

  .hero {
    grid-template-columns: 1fr;
  }

  .heroLeft {
    padding: 3rem 1.5rem;
  }

  .heroSlide {
    min-height: 50vh;
  }

  .about {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .aboutMedia {
    padding: 0 0 1.5rem 1rem;
  }

  .aboutThumbs {
    padding-left: 1rem;
  }

  .contactInner {
    grid-template-columns: 1fr;
    gap: 2.5rem;
  }

  .galleryGrid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .navIn {
    flex-direction: column;
    align-items: flex-start;
    gap: 0.5rem;
  }

  .navLinks {
    flex-wrap: wrap;
  }

  .menuTrack {
    padding-bottom: 1rem;
  }

  .menuCard {
    flex-basis: 260px;
  }

  .galleryGrid {
    grid-template-columns: 1fr;
  }

  .aboutThumbs {
    flex-wrap: wrap;
  }

  .aboutThumbs img {
    width: calc((100% - 1rem) / 2);
  }
}
